import type { Views } from "@/contracts";
import { invokeBackend } from "@/lib/frontend/client";
import { CliSessions } from "@/components/secrets/CliSessions";
import { listCliSessions } from "@/lib/secrets/device";
import type { Metadata } from "next";
import { SimpleShell } from "@/components/chrome/SimpleShell";
import { AppearanceCard } from "@/components/account/AppearanceCard";
import { MfaCard } from "@/components/account/MfaCard";
import { PasswordForm } from "@/components/account/PasswordForm";
import { ProfileForm } from "@/components/account/ProfileForm";
import { SessionsCard } from "@/components/account/SessionsCard";
import { Button } from "@/components/ui/button";
import { Card, PageHeader, SettingsRow } from "@/components/ui/display";
import { prisma } from "@/lib/db";
import { remainingRecoveryCodes } from "@/lib/mfa";
import { requireAuth } from "@/lib/permissions";
import { roleLabel } from "@/lib/roles";
import { listUserWorkspaces } from "@/lib/workspaces";

export const metadata: Metadata = { title: "Account" };

export default async function AccountPage() {
const { user, workspaces, remaining, cliSessions, hasPassword } = await invokeBackend<Views["account-page:loadAccountPage"]>("view", "account-page:loadAccountPage", []);

return (
    <SimpleShell>
      <div className="flex flex-col gap-6">
        <PageHeader title="Your account" description={user.email} />
        <Card padding="lg">
          <SettingsRow title="Profile" description="How the crew sees you across every workspace.">
            <ProfileForm initial={{ name: user.name ?? "", pronouns: user.pronouns ?? "", bio: user.bio ?? "", skills: user.skills, timezone: user.timezone ?? "" }} />
          </SettingsRow>
          <SettingsRow title="Password" description={hasPassword ? "Changing it signs you out on every device." : "You sign in with Google. Add a password as a fallback."}>
            <PasswordForm hasPassword={hasPassword} />
          </SettingsRow>
          <SettingsRow title="Two-step verification" description="A code from your phone at every sign-in.">
            <MfaCard enabled={Boolean(user.mfaEnabledAt)} remainingCodes={remaining} />
          </SettingsRow>
          <SettingsRow title="Appearance" description="Saved in this browser only.">
            <AppearanceCard />
          </SettingsRow>
          <SettingsRow title="Sessions" description="Lost a device? Sign out of every session at once.">
            <SessionsCard />
          </SettingsRow>
          <SettingsRow title="CLI devices" description="Devices authorised to use application Secrets. Revocation takes effect immediately.">
            <CliSessions sessions={cliSessions} timezone={user.timezone ?? "Asia/Kolkata"} />
          </SettingsRow>
          <SettingsRow title="Your data" description="A JSON copy of your profile, memberships, tasks, messages, docs.">
            <Button asChild variant="secondary">
              <a href="/api/account/export" download>Download my data</a>
            </Button>
          </SettingsRow>
          <SettingsRow title="Workspaces" description="Where you're a member.">
            {workspaces.length === 0 ? (
              <p className="text-body-ui text-ink-muted">You aren&apos;t in any workspace yet.</p>
            ) : (
              <ul className="flex flex-col gap-2">
                {workspaces.map((workspace) => (
                  <li key={workspace.id} className="flex items-center justify-between gap-3">
                    <a href={`/w/${workspace.slug}`} className="font-semibold text-ink underline-offset-4 hover:underline">{workspace.name}</a>
                    <span className="text-caption text-ink-muted">{roleLabel(workspace.role)}</span>
                  </li>
                ))}
              </ul>
            )}
          </SettingsRow>
        </Card>
      </div>
    </SimpleShell>
  );
}

import type { Views } from "@/contracts";
import { invokeBackend } from "@/lib/frontend/client";
import type { Metadata } from "next";
import Link from "next/link";
import { AuthFrame } from "@/components/chrome/AuthFrame";
import { AdminMfaForm } from "@/components/admin/AdminMfaForm";
import { Callout } from "@/components/ui/display";
import { prisma } from "@/lib/db";
import { requireSuperAdmin } from "@/lib/permissions";

export const metadata: Metadata = { title: "Confirm it's you" };

/** Fresh TOTP step-up before the instance admin area (valid for 10 minutes). */
export default async function AdminMfaPage() {
const { user } = await invokeBackend<Views["admin-mfa-page:loadAdminMfaPage"]>("view", "admin-mfa-page:loadAdminMfaPage", []);

return (
    <AuthFrame centered title="Confirm it's you." description="Instance admin needs a fresh code from your authenticator app.">
      {user?.mfaEnabledAt ? (
        <AdminMfaForm />
      ) : (
        <Callout tone="warning" title="Two-step verification is off">
          Turn it on in <Link href="/account" className="font-semibold underline underline-offset-4">your account</Link>, then come back.
        </Callout>
      )}
    </AuthFrame>
  );
}

import type { Views } from "@/contracts";
import { invokeBackend } from "@/lib/frontend/client";
import Link from "next/link";
import {
  Card,
  CardHeader,
  PageHeader,
  Chip,
  Callout,
} from "@/components/ui/display";
import { requireSuperAdminMfa } from "@/lib/permissions";
import { prisma } from "@/lib/db";
import { formatDayTime } from "@/lib/format/datetime";
export const metadata = { title: "Backups posture" };
export default async function BackupsPage() {
const { rows, staleBefore, latest } = await invokeBackend<Views["admin-backups-page:loadBackupsPage"]>("view", "admin-backups-page:loadBackupsPage", []);

return (
    <div className="flex flex-col gap-5">
      <PageHeader
        title="Backups posture"
        description="Reported database and file backups. A recorded success does not replace a restore drill."
      />
      <Link
        className="inline-flex min-h-11 items-center underline"
        href="/admin/sso"
      >
        Single sign-on
      </Link>
      {latest.some((x) => !x.row || x.row.startedAt.getTime() < staleBefore) ? (
        <Callout tone="warning" title="Backup evidence needs attention">
          A database or files backup has no success reported in the last 48
          hours. Check the operator’s backup schedule and reporting.
        </Callout>
      ) : null}
      <div className="grid gap-4 sm:grid-cols-2">
        {latest.map(({ kind, row }) => (
          <Card key={kind}>
            <CardHeader title={kind === "DB" ? "Database" : "Files"} />
            <Chip tone={row ? "success" : "warning"}>
              {row ? "Success reported" : "No evidence"}
            </Chip>
            <p className="mt-3 text-caption">
              {row
                ? formatDayTime(row.startedAt, "UTC")
                : "No successful run recorded."}{" "}
              · UTC
            </p>
          </Card>
        ))}
      </div>
      <Card>
        <CardHeader
          title="Recent runs"
          description="Storage locations and raw errors stay out of this view to protect operator credentials."
        />
        {rows.length ? (
          <ul className="divide-y divide-line">
            {rows.map((r) => (
              <li
                key={r.id}
                className="flex flex-wrap items-center justify-between gap-3 py-3"
              >
                <span>
                  {r.kind} · {formatDayTime(r.startedAt, "UTC")} UTC
                </span>
                <Chip tone={r.status === "FAILED" ? "danger" : "neutral"}>
                  {r.status.toLowerCase()}
                </Chip>
                <span className="text-caption">
                  {r.sizeBytes !== null
                    ? `${Number(r.sizeBytes / BigInt(1024))} KB`
                    : "Size not reported"}
                </span>
              </li>
            ))}
          </ul>
        ) : (
          <p>
            No backup runs reported. Ask the operator to connect backup
            reporting.
          </p>
        )}
      </Card>
    </div>
  );
}

import type { Views } from "@/contracts";
