export default async function SsoPage() {
const { providers } = await invokeBackend<Views["admin-sso-page:loadSsoPage"]>("view", "admin-sso-page:loadSsoPage", []);

return (
    <div className="flex flex-col gap-5">
      <PageHeader
        title="Single sign-on"
        description="OpenID Connect for existing, active invited members. New accounts are never created through SSO."
      />
