export const metadata = { title: "Changelog" };
export default async function ChangelogPage({
  params,
}: PageProps<"/w/[workspaceSlug]/changelog">) {const { workspaceSlug } = await params;
const { actor, manage, entries, destinations } = await invokeBackend<Views["w-workspaceSlug-changelog-page:loadChangelogPage"]>("view", "w-workspaceSlug-changelog-page:loadChangelogPage", [{ params,  }]);

return (
    <CollaborationShell
      slug={workspaceSlug}
      title="Changelog"
      description="A shared record of what changed, when it shipped, and why it matters."
    >
      {manage ? (
        <Disclosure title="Write an entry" open={!entries.length}>
          <ActionForm
            slug={workspaceSlug}
            action={changelogAction}
            hidden={{ op: "create" }}
            label="Save draft"
            primary
            reset
            fields={[
              { name: "title", label: "Title", required: true },
              {
                name: "bodyMd",
                label: "What changed",
                type: "textarea",
                required: true,
              },
              { name: "version", label: "Version" },
              {
                name: "tags",
                label: "Tags",
                type: "tags",
