                    confirm="Publish this entry and send it to the selected destinations? Published entries remain as a record."
                    fields={[
                      {
                        name: "publishedAt",
                        label: "Release date",
                        type: "date",
                        value: new Date().toISOString().slice(0, 10),
                        required: true,
                      },
                      {
                        name: "destinationIds",
                        label: "Send to",
                        type: "multi",
                        options: destinations.map((d) => ({
                          value: d.id,
                          label: d.name,
                        })),
                      },
                    ]}
                  />
                </details>
              </>
            ) : null}
          </Section>
        ))
      )}
    </CollaborationShell>
  );
}

