          tasks={chartTasks}
          startsAt={cycle.startsAt}
          endsAt={cycle.endsAt}
          timezone={actor.workspace.timezone}
        />
      </Section>
      {snapshot.success ? (
        <Section title="Cycle review">
          <TextBody>
            {snapshot.data.review ||
