      {cycle.status === "COMPLETED" ? (
        <Disclosure title="Write a cycle review">
          <ActionForm
            slug={workspaceSlug}
            action={cycleAction}
            hidden={{ op: "review", cycleId }}
            label="Save review"
            fields={[
