      {cycle.status !== "COMPLETED" ? (
        <Disclosure title="Edit cycle">
          <ActionForm
            slug={workspaceSlug}
            action={cycleAction}
            hidden={{ op: "edit", cycleId }}
            label="Save cycle"
            fields={[
