            hidden={{ op: "complete", cycleId }}
            label="Complete cycle"
            confirm="Complete this cycle and carry unfinished tasks to the selected cycle?"
            fields={[
              {
                name: "review",
                label: "What worked and what comes next",
                type: "textarea",
