          {results.length === 0 ? (
            <EmptyState patch title={`No pages match “${query}”.`}>Try fewer words, or check the archived pages.</EmptyState>
          ) : (
            <Card padding="none">
              <ul className="divide-y divide-line">
                {results.map((doc) => (
                  <li key={doc.id}>
                    <Link href={`/w/${workspace.slug}/docs/${doc.id}`} className="flex flex-col gap-1 px-5 py-4 transition-colors duration-[120ms] hover:bg-subtle">
