export default async function OnboardingPage({ params }: PageProps<"/w/[workspaceSlug]/onboarding">) {const { workspaceSlug } = await params;
const { ctx, manage, runs, templates, members } = await invokeBackend<Views["w-workspaceSlug-onboarding-page:loadOnboardingPage"]>("view", "w-workspaceSlug-onboarding-page:loadOnboardingPage", [{ params,  }]);

