l>{run.status === "OPEN" && (manage || run.subjectUserId === ctx.user.id && run.kind !== "OFFBOARDING") ? <div className="mt-4 flex flex-wrap gap-3"><ActionButton action={mutatePeople.bind(null, workspaceSlug, "complete")} input={{ id: run.id }}>Complete checklist</ActionButton>{manage && run.kind === "OFFBOARDING" ? <ActionButton action={mutatePeople.bind(null, workspaceSlug, "complete")} input={{ id: run.id, suspend: true }} destructive confirm="Complete offboarding and suspend access?">Complete and suspend…</ActionButton> : null}</div> : null}</Card>; })}{manage ? <div className="grid gap-6 md:grid-cols-2"><Card><CardHeader title="Start a checklist" /><EditorForm action={mutatePeople.bind(null, workspaceSlug, "start")} label="Assign checklist" fields={[{ name: "templateId", label: "Template", type: "select", options: templates.map(t => ({ value: t.id, label: t.name })) }, { name: "userId", label: "Member", type: "select", options: members.map(m => ({ value: m.id, label: m.name })) }]} /></Card><Card><CardHeader title="Start offboarding" description="Build a handover checklist from vault access, service ownership, equipment, keys and external accounts." /><EditorForm action={mutatePeople.bind(null, workspaceSlug, "offboarding")} label="Generate handover" fields={[{ name: "userId", label: "Leaving member", type: "select", options: members.filter(m => m.id !== ctx.user.id && (ctx.membership.role === "OWNER" || ["MEMBER", "GUEST"].includes(m.role))).map(m => ({ value: m.id, label: m.name })) }]} /></Card></div> : null}</div>;
