ainer team", type: "select", parse: "nullable", value: t.trainerTeamId ?? "", options: [{ value: "", label: "No trainer team" }, ...teams.map(team => ({ value: team.id, label: team.name }))] }]} /></details>)}</Card> : null}<div className="grid gap-6 md:grid-cols-2">{trainable.length ? <Card><CardHeader title="Grant a sign-off" /><EditorForm action={mutatePeople.bind(null, workspaceSlug, "grantCert")} label="Grant sign-off" fields={[{ name: "certTypeId", label: "Training", type: "select", options: trainable.map(t => ({ value: t.id, label: t.name })) }, { name: "userId", label: "Member", type: "select", options: members.filter(m => canManageRota(ctx.membership) || m.id !== ctx.user.id).map(m => ({ value: m.id, label: m.name })) }]} /></Card> : null}{canManageRota(ctx.membership) ? <Card><CardHeader title="New training type" /><EditorForm action={mutatePeople.bind(null, workspaceSlug, "certType")} label="Create training type" fields={[{ name: "name", label: "Training name", required: true }, { name: "description", label: "Description", type: "textarea" }, { name: "validityDays", label: "Valid for days", type: "number", parse: "nullableNumber", min: 1, max: 3650, helper: "Leave empty for a sign-off that does not expire." }, { name: "trainerIds", label: "Individual trainers", type: "choices", options: members.filter(m => m.role !== "GUEST").map(m => ({ value: m.id, label: m.name })) }, { name: "trainerTeamId", label: "Trainer team", type: "select", parse: "nullable", options: [{ value: "", label: "Admins only" }, ...teams.map(t => ({ value: t.id, label: t.name }))] }]} /></Card> : null}</div></div>;
