nButton action={mutateRota.bind(null, workspaceSlug, "signup")} input={s.id}>Sign up</ActionButton>}{s.assignments.flatMap(a => a.swapRequests).filter(r => r.fromUserId !== ctx.user.id && (!r.toUserId || r.toUserId === ctx.user.id)).map(r => <ActionButton key={r.id} action={mutateRota.bind(null, workspaceSlug, "acceptSwap")} input={r.id}>Cover this shift</ActionButton>)}</div> : null}</Card>; })}</div> : <EmptyState patch title="No shifts this week. Pick another week or ask a lead to add one." />}{manage ? <div className="grid gap-6 md:grid-cols-2"><Card><CardHeader title="Schedule shifts" /><EditorForm action={mutateRota.bind(null, workspaceSlug, "schedule")} label="Schedule shifts" fields={[{ name: "shiftTypeId", label: "Shift template", type: "select", options: data.types.filter(t => canManageRota(ctx.membership) || managingTeams.some(mt => mt.id === t.teamId)).map(t => ({ value: t.id, label: t.name })) }, { name: "startsAt", label: "Starts", type: "datetime-local", required: true }, { name: "endsAt", label: "Ends", type: "datetime-local", required: true }, { name: "capacity", label: "Places", type: "number", parse: "nullableNumber", min: 1, max: 100, helper: "Leave empty to use the template default." }, { name: "weeks", label: "Repeat weekly for", type: "number", value: 1, min: 1, max: 12, helper: "Choose 1 for a single shift, up to 12 weeks." }, { name: "location", label: "Location" }, { name: "notes", label: "Notes", type: "textarea" }]} /></Card><Card><CardHeader title="New shift template" /><EditorForm action={mutateRota.bind(null, workspaceSlug, "template")} label="Create shift template" fields={[{ name: "name", label: "Name", required: true }, { name: "teamId", label: "Team", type: "select", parse: "nullable", options: [...(canManageRota(ctx.membership) ? [{ value: "", label: "Whole workspace" }] : []), ...managingTeams.map(t => ({ value: t.id, label: t.name }))] }, { name: "defaultCapacity", label: "Default places", type: "number", value: 1, min: 1, max: 100 }, { name: "requiresCertTypeId", label: "Required sign-off", type: "select", parse: "nullable", options: [{ value: "", label: "No sign-off required" }, ...data.certTypes.map(c => ({ value: c.id, label: c.name }))] }, { name: "requiresKeyholder", label: "Needs a keyholder", type: "checkbox" }]} /></Card></div> : null}{manage ? <Card><CardHeader title="Shift templates" description="Existing shifts keep their capacity. Training and keyholder requirements apply to all shifts using the template." />{data.types.filter(t => canManageRota(ctx.membership) || managingTeams.some(team => team.id === t.teamId)).map(t => <details key={t.id} className="border-t border-line py-3"><summary className="min-h-11 cursor-pointer text-title">{t.name}</summary><EditorForm action={mutateRota.bind(null, workspaceSlug, "template")} fixed={{ id: t.id }} label="Save template" fields={[{ name: "name", label: "Template name", required: true, value: t.name }, { name: "teamId", label: "Team", type: "select", parse: "nullable", value: t.teamId ?? "", options: [...(canManageRota(ctx.membership) ? [{ value: "", label: "Whole workspace" }] : []), ...managingTeams.map(team => ({ value: team.id, label: team.name }))] }, { name: "defaultCapacity", label: "Default places", type: "number", min: 1, max: 100, value: t.defaultCapacity }, { name: "requiresCertTypeId", label: "Required sign-off", type: "select", parse: "nullable", value: t.requiresCertTypeId ?? "", options: [{ value: "", label: "No sign-off required" }, ...data.certTypes.map(c => ({ value: c.id, label: c.name }))] }, { name: "requiresKeyholder", label: "Needs a keyholder", type: "checkbox", value: t.requiresKeyholder }]} /></details>)}</Card> : null}</div>;
