export default async function Page({ params, searchParams }: PageProps<"/w/[workspaceSlug]/services/monitors/[id]">) {const { workspaceSlug, id } = await params, query = await searchParams;
const { workspace, monitor, manage, now, hours, checks, days, incidents, pings, summary } = await invokeBackend<Views["w-workspaceSlug-services-monitors-id-page:loadPage"]>("view", "w-workspaceSlug-services-monitors-id-page:loadPage", [{ params, searchParams }]);

return <div className="space-y-6"><Link className="text-accent-text" href={`/w/${workspaceSlug}/services`}>Back to Services</Link><div className="flex flex-wrap items-center justify-between gap-3"><h1 className="min-w-0 break-words text-h1">{monitor.name}</h1><Status status={monitor.lastStatus} /></div>
 <div className="grid gap-4 sm:grid-cols-4">{[1, 7, 30, 90].map(n => <Card key={n}><p className="text-label">{n === 1 ? "24 hours" : `${n} days`} uptime</p><p className="mt-3 text-h3 tabular-nums">{formatUptime(uptimePercent(n === 1 ? summary : mergeRollups(days.filter(r => r.bucketStart.getTime() >= now.getTime() - n * 86400000))))}</p></Card>)}</div>
 <Card><div className="flex gap-4"><h2 className="text-h3">Latency</h2><Link href="?range=1h" className="text-accent-text">1 hour</Link><Link href="?range=24h" className="text-accent-text">24 hours</Link></div><Sparkline values={[...checks].filter(c => c.checkedAt.getTime() >= now.getTime() - hours * 3600000).reverse().map(c => c.latencyMs)} /><p className="text-caption text-ink-muted">p50 {summary.latencyP50 ?? "—"} ms · p95 {summary.latencyP95 ?? "—"} ms · {workspace.timezone}</p></Card>
 <Card><h2 className="mb-4 text-h3">Uptime history</h2><UptimeBars bars={dailyBars(days, 90, now).map(b => ({ day: b.day.toISOString().slice(0, 10), uptime: b.uptime }))} /></Card>
 <Card><h2 className="mb-4 text-h3">Recent checks</h2><div className="overflow-x-auto"><Table className="w-full text-left text-body-ui"><THead><TR><TH className="py-3">Time</TH><TH>Status</TH><TH>Latency</TH><TH>Result</TH></TR></THead><TBody>{checks.slice(0, 50).map(c => <TR key={c.id} className="border-t border-line"><TD className="py-3">{formatDayTime(c.checkedAt, workspace.timezone)}</TD><TD><Status status={c.inMaintenance ? "MAINTENANCE" : c.status} /></TD><TD>{c.latencyMs === null ? "—" : `${c.latencyMs} ms`}</TD><TD>{c.statusCode ?? ""} {c.error ?? ""}<p className="max-w-lg break-words text-caption text-ink-muted">{c.message}</p></TD></TR>)}</TBody></Table></div>{!checks.length ? <p>No checks yet. The checker will pick this up shortly.</p> : null}</Card>
