run-your-job && curl --fail "$HEARTBEAT_URL/0" || curl --fail "$HEARTBEAT_URL/fail"`}</pre><p className="mt-3 text-caption text-ink-muted">Stored token hint: {monitor.heartbeatTokenHint ?? "None"}. Rotate to get a new URL.</p>{manage ? <CommandForm slug={workspaceSlug} command="rotateHeartbeat" fixed={{ id }} label="Regenerate heartbeat URL" confirmText="Invalidate the current heartbeat URL and generate a new one?" /> : null}<ul className="mt-4 space-y-2">{pings.map(p => <li key={p.id}>{formatDayTime(p.receivedAt, workspace.timezone)} · {p.kind.toLowerCase()} {p.exitCode !== null ? `(${p.exitCode})` : ""} {p.durationMs !== null ? `${p.durationMs} ms` : ""}</li>)}</ul></Card> : null}
 <Card><h2 className="mb-3 text-h3">Incidents</h2>{incidents.map(i => <p key={i.id} className="py-2"><Link className="text-accent-text" href={`/w/${workspaceSlug}/services/incidents/${i.number}`}>INC-{i.number}: {i.title}</Link> <Status status={i.status} /></p>)}{!incidents.length ? <p>No incidents recorded.</p> : null}</Card>
 {manage ? <Card><h2 className="mb-3 text-h3">Manage monitor</h2><Link className="inline-flex min-h-11 items-center text-accent-text" href={`/w/${workspaceSlug}/services/monitors/${id}/edit`}>Edit monitor</Link><div className="grid gap-4 sm:grid-cols-3"><CommandForm slug={workspaceSlug} command="pause" fixed={{ id, enabled: !monitor.enabled }} label={monitor.enabled ? "Pause monitor" : "Resume monitor"} /><CommandForm slug={workspaceSlug} command="testMonitor" fixed={{ id }} label="Test now" /><CommandForm slug={workspaceSlug} command="testAlert" fixed={{ id }} label="Send test alert" /></div><details className="mt-4"><summary className="min-h-11 text-danger-fg">Delete monitor…</summary><CommandForm slug={workspaceSlug} command="deleteMonitor" fixed={{ id }} confirmText="Delete this monitor and all of its checks?" label="Delete monitor" redirectTo={`/w/${workspaceSlug}/services`} /></details></Card> : null}</div>;
}

