          <ActionForm
            slug={workspaceSlug}
            action={signatureAction}
            hidden={{ op: "decline", requestId }}
            label="Decline request…"
            destructive
            confirm="Decline this acknowledgement request?"
          />
        </>
      ) : null}
      {request.status === "PENDING" &&
      (admin(actor) || request.createdById === actor.user.id) ? (
