      <section aria-label="Connected accounts" className="grid gap-3 sm:grid-cols-2">{data.accounts.map(account => { const counts = data.followers.find(v => v.accountId === account.id)!; return <Card key={account.id}><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-caption text-ink-muted">{PLATFORM_LABELS[account.platform]}</p><AccountStatus status={account.status} /></div><h2 className="mt-3 text-title"><Link className="text-accent-text underline" href={`/w/${workspaceSlug}/social/accounts/${account.id}`}>{account.displayName}</Link></h2><p className="mt-2 text-h3 tabular-nums">{metricValue(counts.value)} <span className="text-label text-ink-muted">followers</span></p><dl className="mt-3 grid grid-cols-3 gap-2">{[7, 28, 90].map(d => <div key={d}><dt className="text-caption text-ink-muted">{d}-day change</dt><dd className="text-label tabular-nums">{counts.deltas[d] == null ? "Unavailable" : `${counts.deltas[d]! > 0 ? "+" : ""}${metricValue(counts.deltas[d])}`}</dd></div>)}</dl>{account.lastError ? <p className="mt-3 text-caption text-danger-fg">{account.lastError}</p> : null}{account.status === "DEMO" ? <p className="mt-3 text-caption text-ink-muted">Sample data for exploring Social.</p> : null}</Card>; })}</section><MetricChart daily={data.daily} /><section className="space-y-3"><h2 className="text-h4">Top posts by likes and reactions</h2>{data.topPosts.length ? <PostTable posts={data.topPosts} timezone={ctx.workspace.timezone} caption={`Posts published in the last ${f.days} days`} /> : <Card>No posts in this period. Try a longer period.</Card>}</section>
    </>}
  </div>;
}

