import type { Views } from "@/contracts";
import { invokeBackend } from "@/lib/frontend/client";
import type { Metadata } from "next";
import { notFound, redirect } from "next/navigation";
import { TaskDetail } from "@/components/tasks/TaskDetail";
import { requireWorkspace } from "@/lib/permissions";
import { parseTaskReference } from "@/lib/tasks/links";
import { getTaskDetail } from "@/lib/tasks/queries";

async function load(workspaceSlug: string, ref: string) {
  const context = await requireWorkspace(workspaceSlug, "GUEST");
  const reference = parseTaskReference(decodeURIComponent(ref));
  const task = reference ? await getTaskDetail(context, reference.number) : null;
  if (!task || (reference?.key && task.project?.key !== reference.key)) return { context, task: null };
  return { context, task };
}

export async function generateMetadata({ params }: PageProps<"/w/[workspaceSlug]/t/[ref]">): Promise<Metadata> {return await invokeBackend<Views["w-workspaceSlug-t-ref-page:loadgenerateMetadata"]>("view", "w-workspaceSlug-t-ref-page:loadgenerateMetadata", [{ params,  }]);}

/**
 * Short task links: `/w/<slug>/t/BOT-12`, `/t/12` or `/t/%2312`. Project
 * tasks redirect to their board page; tasks without a project (meeting
 * action items, personal tasks) live here.
 */
export default async function ShortTaskPage({ params }: PageProps<"/w/[workspaceSlug]/t/[ref]">) {const { workspaceSlug, ref } = await params;
const { context, task } = await invokeBackend<Views["w-workspaceSlug-t-ref-page:loadShortTaskPage"]>("view", "w-workspaceSlug-t-ref-page:loadShortTaskPage", [{ params,  }]);

return <TaskDetail slug={context.workspace.slug} initial={task} variant="page" />;
}

