endsAt,actor.workspace.timezone)}</span><span>{durationLabel(r.minutes)}</span></RecordRow>)}</ul></Card> : <Empty patch line={status ? "No hours match this filter." : "No hours logged yet."} href={status ? base : `${base}/new`} action={status ? "Clear filter" : "Log hours"} />}<Pager base={base} page={page} total={data.total} query={{ status,q:month }} /></Frame>;
